101	      const t = (e.textContent || '').trim();
102	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
103	      // 只数最内层节点，避免父容器重复计数
104	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
105	      const r = e.getBoundingClientRect();
106	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
107	    }
108	    return n;
109	  }
110	  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
111	  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
112	  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
113	  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
114	  function scanProducts() {
115	    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
116	    const products = [];
117	    let cur = null;
118	    for (const tr of rows) {
119	      const t = tr.textContent || '';
120	      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
121	      if (spu) {
122	        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
123	        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
124	        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
125	        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
126	          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
127	          .sort((a, b) => b.length - a.length)[0] || '';
128	        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
129	        products.push(cur);
130	      }
131	      if (cur) {
132	        if (/商品流量待关注/.test(t)) cur.watch = true;
133	        if (/商品流量近期有下降/.test(t)) cur.decline = true;
134	      }
135	    }
136	    return products;
137	  }
138	  function readTraffic() {
139	    const all = [...document.querySelectorAll('*')];
140	    return {
141	      watch: readChipCount(all, '商品流量待关注'),
142	      decline: countDeclineBadges(all),
143	    };
144	  }
145	  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
146	  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
147	  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
148	  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
149	  let tries = 0;
150	  let lastKey = '';
151	  setInterval(() => {
152	    tries++;
153	    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
154	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
155	    const { watch, decline } = readTraffic();
156	    const msg = { type: 'chipStats', store: readStoreName() };
157	    if (watch != null) msg.trafficWatch = watch;
158	    let watchItems = [];
159	    let declineItems = [];
160	    if (gridReady) {
161	      const products = scanProducts();
162	      watchItems = products.filter((p) => p.watch).map(pickItem);
163	      declineItems = products.filter((p) => p.decline).map(pickItem);
164	      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
165	      msg.watchItems = watchItems;
166	      msg.declineItems = declineItems;
167	    }
168	    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
169	    const readyOrTimedOut = gridReady || tries > 8;
170	    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
171	    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
172	    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
173	      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
