async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  // Click Product, Price, Ads submenu titles to expand
  const titles = [...document.querySelectorAll('.rocket-menu-submenu-title, .rocket-menu-submenu')];
  const want = ['Product', 'Price', 'Ads', 'Promotion', 'Webhook'];
  const clicks = [];
  for (const el of titles) {
    const t = (el.textContent || '').trim().split('\n')[0].slice(0, 30);
    if (want.some(w => t === w || t.startsWith(w))) {
      el.click();
      clicks.push(t);
      await sleep(300);
    }
  }
  await sleep(500);
  const items = [...document.querySelectorAll('.rocket-menu-item, .rocket-menu-submenu-title')];
  const texts = items.map(el => (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 100)).filter(Boolean);
  return { clicks, texts };
}

async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  // Expand nested under Product: Manage Products, Add Products
  const all = [...document.querySelectorAll('.rocket-menu-submenu, .rocket-menu-item, .rocket-menu-submenu-title')];
  for (const el of all) {
    const t = (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 40);
    if (t === 'Manage Products' || t === 'Add Products' || t.startsWith('Manage Products') || t.startsWith('Add Products')) {
      el.click();
      await sleep(400);
    }
  }
  await sleep(600);
  const items = [...document.querySelectorAll('.rocket-menu-item, .rocket-menu-submenu-title')];
  return items.map(el => (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 120)).filter(Boolean);
}

