    const items = [...document.querySelectorAll('.rocket-menu-item')];
    const target = items.find(el => (el.textContent || '').trim() === name || (el.textContent || '').includes(name));
    if (!target) return { name, err: 'not found' };
    target.click();
    await sleep(1800);
    const main = document.querySelector('main') || document.body;
    const t = main.innerText || '';
