      name,
      url: location.href,
      // focus on request/response field descriptions
      snippet: t.slice(t.indexOf(name), t.indexOf(name) + 6000)
    };
  };
  const results = [];
  for (const n of [
    'bg.local.goods.sale.status.set',
    'bg.local.goods.publish.status.get',
    'temu.local.goods.list.retrieve',
    'temu.local.goods.recommendedprice.query',
    'temu.searchrec.ad.reports.goods.query'
  ]) {
