console.log('normalize ok', g);

// diff first round no alert
let r = diffCatalog(null, { activeMap: { a: {name:'A'} }, lowTrafficMap: {}, restrictedMap: {}, counts: {active:1,lowTraffic:0,restricted:0} }, {});
if (!r.isFirst || r.events.some(e=>e.severity==='alert')) throw new Error('first round should not alert');
// second round delist
r = diffCatalog(r.nextSnap, { activeMap: {}, lowTrafficMap: {}, restrictedMap: {}, counts: {active:0,lowTraffic:0,restricted:0} }, {});
// active went 1->0, prevN=1 < 10 so incomplete guard not applied; delist should fire
if (!r.events.some(e=>e.type==='delist')) throw new Error('expected delist '+JSON.stringify(r.events));
console.log('diff delist ok', r.events);

// incomplete guard
const big = {};
for (let i=0;i<20;i++) big['id'+i] = {name:'n'+i};
r = diffCatalog({ activeMap: big, lowTrafficMap: {}, restrictedMap: {} }, { activeMap: { id0: {name:'n0'} }, lowTrafficMap: {}, restrictedMap: {}, counts: {active:1} }, {});
if (!r.skipDelistUpdate) throw new Error('expected skip');
console.log('incomplete guard ok');

// low traffic add
r = diffCatalog(
  { activeMap: {a:{name:'A'}}, lowTrafficMap: {}, restrictedMap: {} },
  { activeMap: {a:{name:'A'}}, lowTrafficMap: {a:{name:'A'}}, restrictedMap: {}, counts: {active:1,lowTraffic:1,restricted:0} },
  {}
);
if (!r.events.some(e=>e.type==='low_traffic')) throw new Error('low traffic');
console.log('low traffic ok');
console.log('ALL UNIT CHECKS PASSED');
