  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(1500);
  // accept disclaimer if any
  for (const el of document.querySelectorAll('button, a, .ui-btn')) {
    const t = (el.textContent || '').trim();
    if (/同意|确认|进入|继续|我知道了|Accept|OK/.test(t)) { el.click(); await sleep(800); break; }
  }
  await sleep(1000);
  const text = (document.body.innerText || '').slice(0, 8000);
  const links = [...document.querySelectorAll('a, .ui-menu-item, [class*=menu] span, [class*=tree] span')]
    .map(e => (e.textContent||'').trim().replace(/\s+/g,' ').slice(0,80))
    .filter(t => t && t.length < 60)
    .slice(0, 100);
  return { title: document.title, url: location.href, text, links: [...new Set(links)].slice(0,80) };
}

async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  await sleep(1000);
  // Collect all nav/menu items
  const nodes = [...document.querySelectorAll('a, [class*="menu"] span, [class*="tree"] span, [class*="sidebar"] a, li, .ui-tree-node-content')];
  const texts = nodes.map(e => (e.textContent || '').trim().replace(/\s+/g, ' ')).filter(t => t && t.length >= 2 && t.length <= 80);
