export async function probeSellfox(cfg) {
  const client = createSellfoxClient({
    baseUrl: cfg.baseUrl,
    clientId: cfg.clientId,
    clientSecret: cfg.clientSecret,
    debug: true,
  });
  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
