/**
 * 赛狐 Temu 下架监测一轮
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import { createSellfoxClient } from './client.js';
import { fetchAllCrossParents, groupByShop, SELECT_STATUS } from './products.js';
import { diffOnSale, formatDelistLines } from './diff.js';
import { shopNameMap } from './config.js';
import { sendFeishu } from '../feishu.js';
import { log } from '../logger.js';

function loadState(path) {
  try {
    if (!existsSync(path)) return { stores: {} };
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return { stores: {} };
  }
}

function saveState(path, state) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(state, null, 2), 'utf8');
}

/**
 * @param {object} cfg loadSellfoxConfig()
 * @param {{ dryRun?: boolean }} [opts]
 */
export async function runSellfoxOnce(cfg, opts = {}) {
  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
  if (!cfg.clientId || !cfg.clientSecret) throw new Error('缺少 clientId/clientSecret');
  if (!shops.length) throw new Error('没有店铺');

  const client = createSellfoxClient({
    baseUrl: cfg.baseUrl,
    clientId: cfg.clientId,
    clientSecret: cfg.clientSecret,
    debug: cfg.debug,
  });

  const shopIds = shops.map((s) => s.shopId);
  const names = shopNameMap(cfg);

  log.info(`Sellfox 拉取 Temu 跨境父体：shops=${shopIds.join(',')} dateType=${cfg.dateType} lookback=${cfg.lookbackDays}d`);
  const { items, meta } = await fetchAllCrossParents(client, {
    shopIds,
    pageSize: cfg.pageSize,
    maxPagesPerWindow: cfg.maxPagesPerWindow,
    dateType: cfg.dateType,
    lookbackDays: cfg.lookbackDays,
  });
  log.info(`拉取完成 unique=${meta.unique} windows=${meta.windows}`);

  const grouped = groupByShop(items, names);
  const state = loadState(cfg.stateFile);
  if (!state.stores) state.stores = {};

  const summary = [];

  for (const shop of shops) {
    const sid = shop.shopId;
    const name = names[sid] || shop.name || sid;
    const g = grouped[sid] || {
      shopId: sid,
      shopName: name,
      onSaleMap: {},
      statusCounts: {},
    };
    const onSaleN = Object.keys(g.onSaleMap).length;
    log.info(
      `${name}(${sid}) 在售(12)=${onSaleN} 状态分布=${JSON.stringify(g.statusCounts || {})}`,
    );

    const prev = state.stores[sid]?.snapshot || null;
    const { events, nextSnap, isFirst, skipUpdate } = diffOnSale(prev, {
      onSaleMap: g.onSaleMap,
      statusCounts: g.statusCounts,
    });

    if (isFirst) {
      log.info(`${name} 首轮：建立在售基准 ${onSaleN}，不告警`);
    } else if (skipUpdate) {
      log.warn(`${name} 跳过下架更新（扫描疑似不全）`);
    }

    const alertEvents = cfg.alerts?.delist === false
      ? []
      : events.filter((e) => e.severity === 'alert');

    if (alertEvents.length && !opts.dryRun) {
      const lines = formatDelistLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl });
      await sendFeishu(
        { feishuWebhooks: cfg.feishuWebhooks, feishuSecret: cfg.feishuSecret },
        { title: '🔔 Temu 下架监测（赛狐）', template: 'red', lines },
      );
      log.info(`${name} 已告警下架 ${alertEvents.reduce((n, e) => n + (e.items?.length || 0), 0)} 个`);
    } else if (alertEvents.length && opts.dryRun) {
      log.info(`${name} dryRun:`, formatDelistLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl }));
    } else if (!isFirst && !skipUpdate) {
      log.info(`${name} 本轮无下架`);
    }

    state.stores[sid] = {
      name,
      latest: {
        onSaleCount: nextSnap.onSaleCount,
        statusCounts: g.statusCounts,
        ts: Date.now(),
      },
      snapshot: nextSnap,
    };
    summary.push({
      shopId: sid,
      store: name,
      onSale: nextSnap.onSaleCount,
      statusCounts: g.statusCounts,
      events: events.map((e) => e.type),
      isFirst,
      skipUpdate,
    });
  }

  // 配置了但本轮 API 完全没返回的店也建空基准提示
  for (const shop of shops) {
    if (!summary.find((s) => s.shopId === shop.shopId)) {
      summary.push({ shopId: shop.shopId, store: shop.name, onSale: 0, note: '无数据' });
    }
  }

  if (!opts.dryRun) saveState(cfg.stateFile, state);
  return { meta, summary, onSaleStatus: SELECT_STATUS.ON_SALE };
}

/** 只读探测：拉一窗并打印分布 */
export async function probeSellfox(cfg) {
  const client = createSellfoxClient({
    baseUrl: cfg.baseUrl,
    clientId: cfg.clientId,
    clientSecret: cfg.clientSecret,
    debug: true,
  });
  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
  const shopIds = shops.map((s) => s.shopId);
  const { items, meta } = await fetchAllCrossParents(client, {
    shopIds,
    pageSize: cfg.pageSize,
    maxPagesPerWindow: cfg.maxPagesPerWindow,
    dateType: cfg.dateType,
    lookbackDays: Math.min(cfg.lookbackDays || 30, 30),
  });
  const grouped = groupByShop(items, shopNameMap(cfg));
  const byStatus = {};
  for (const it of items) {
    const st = it.selectStatus || '<empty>';
    byStatus[st] = (byStatus[st] || 0) + 1;
  }
  return {
    meta,
    byStatus,
    byShop: Object.fromEntries(
      Object.entries(grouped).map(([id, g]) => [
        id,
        {
          name: g.shopName,
          onSale12: Object.keys(g.onSaleMap).length,
          statusCounts: g.statusCounts,
        },
      ]),
    ),
    sampleOnSale: items
      .filter((i) => i.selectStatus === SELECT_STATUS.ON_SALE)
      .slice(0, 5)
      .map((i) => ({
        shop: i.shopName,
        skcId: i.skcId,
        parentId: i.parentId,
        name: i.productName.slice(0, 40),
        selectStatus: i.selectStatus,
      })),
  };
}

/**
 * 赛狐开放平台客户端（对齐 sellfox-bridge/bridge/clients/sellfox.py）
 * - GET /api/oauth/v2/token.json
 * - 业务 POST：query 带 access_token/client_id/timestamp/nonce/sign
 * - 签名：HMAC-SHA256(client_secret, 字典序 k=v 用 & 拼接)；body 不参与签名
 */
import crypto from 'node:crypto';
import { log } from '../logger.js';

export class SellfoxError extends Error {
  constructor(code, msg, requestId) {
    super(`sellfox code=${code} msg=${msg}${requestId ? ` requestId=${requestId}` : ''}`);
    this.code = code;
    this.msg = msg;
    this.requestId = requestId;
  }
}

/**
 * @param {{ baseUrl?: string, clientId: string, clientSecret: string, timeoutMs?: number, debug?: boolean }} opts
 */
export function createSellfoxClient(opts) {
  const baseUrl = String(opts.baseUrl || 'https://openapi.sellfox.com').replace(/\/$/, '');
  const clientId = String(opts.clientId || '').trim();
  const clientSecret = String(opts.clientSecret || '').trim();
  const timeoutMs = Number(opts.timeoutMs) || 60000;
  const debug = !!opts.debug;

  if (!clientId || !clientSecret) {
    throw new Error('sellfox 缺少 clientId / clientSecret');
  }

  let token = null;
  let tokenExpireAt = 0; // epoch seconds

  async function getToken() {
    const now = Date.now() / 1000;
    if (token && now < tokenExpireAt - 600) return token;
    const url = new URL(`${baseUrl}/api/oauth/v2/token.json`);
    url.searchParams.set('client_id', clientId);
    url.searchParams.set('client_secret', clientSecret);
    url.searchParams.set('grant_type', 'client_credentials');
    const resp = await fetch(url, { method: 'GET', signal: AbortSignal.timeout(timeoutMs) });
    const body = await resp.json().catch(() => ({}));
    if (body.code !== 0) {
      throw new SellfoxError(body.code, body.msg || resp.statusText, body.requestId);
    }
    token = body.data.access_token;
    // 文档/实调：expires_in 多为毫秒
    const exp = Number(body.data.expires_in) || 86400000;
    tokenExpireAt = now + (exp > 1e6 ? exp / 1000 : exp);
    log.info('Sellfox token refreshed');
    return token;
  }

  function sign(urlPath, accessToken, timestamp, nonce) {
    const params = {
      access_token: accessToken,
      client_id: clientId,
      method: 'post',
      nonce: String(nonce),
      timestamp: String(timestamp),
      url: urlPath,
    };
    const data = Object.keys(params)
      .sort()
      .map((k) => `${k}=${params[k]}`)
      .join('&');
    return crypto.createHmac('sha256', clientSecret).update(data, 'utf8').digest('hex');
  }

  /**
   * @param {string} urlPath 如 /api/multiplatform/temu/product/getParentPageList.json
   * @param {object} body
   */
  async function post(urlPath, body = {}, retries = 3) {
    let lastErr = null;
    for (let attempt = 0; attempt < retries; attempt++) {
      const accessToken = await getToken();
      const ts = Date.now();
      const nonce = Math.floor(Math.random() * 99999) + 1;
      const q = new URLSearchParams({
        access_token: accessToken,
        client_id: clientId,
        timestamp: String(ts),
        nonce: String(nonce),
        sign: sign(urlPath, accessToken, ts, nonce),
      });
      const url = `${baseUrl}${urlPath}?${q}`;
      if (debug) log.info('Sellfox POST', urlPath, body);

      try {
        const resp = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
          signal: AbortSignal.timeout(timeoutMs),
        });
        const text = await resp.text();
        let data;
        try {
          data = JSON.parse(text);
        } catch {
          lastErr = new Error(`非 JSON HTTP ${resp.status}: ${text.slice(0, 200)}`);
          await sleep(2 ** attempt * 400);
          continue;
        }
        if (data.code === 0) return data.data;
        // 40019 限流：退避重试
        if ((data.code === 40019 || /超过限制|rate|限流/i.test(String(data.msg || ''))) && attempt < retries - 1) {
          const wait = 1500 * (attempt + 1);
          log.warn(`Sellfox 限流 code=${data.code}，${wait}ms 后重试`);
          await sleep(wait);
          continue;
        }
        if (String(data.msg || '').toLowerCase().includes('token') && attempt < retries - 1) {
          token = null;
          continue;
        }
        throw new SellfoxError(data.code, data.msg, data.requestId);
      } catch (e) {
        if (e instanceof SellfoxError) throw e;
        lastErr = e;
        log.warn(`Sellfox ${urlPath} 网络异常(${attempt + 1}): ${e.message}`);
        await sleep(2 ** attempt * 400);
      }
    }
    throw new SellfoxError(-1, `重试仍失败: ${lastErr && lastErr.message}`);
  }

  /** Temu 跨境父体分页（startDate/endDate 间隔 ≤30 天） */
  async function temuCrossParentPage({
    pageNo = 1,
    pageSize = 100,
    shopIds,
    dateType = 'updateDate',
    startDate,
    endDate,
  } = {}) {
    const body = {
      pageNo: Number(pageNo),
      pageSize: Number(pageSize),
      dateType: dateType || 'updateDate',
      startDate: startDate || '2020-01-01',
      endDate: endDate || ymd(new Date()),
    };
    if (shopIds?.length) body.shopIdList = shopIds.map(String);
    return post('/api/multiplatform/temu/product/getParentPageList.json', body);
  }

  return { post, getToken, temuCrossParentPage, baseUrl, clientId };
}

function ymd(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

export { ymd };

